create table public.media_categories(id bigint generated always as identity primary key,code text not null unique check(code ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),name_fa text not null,name_en text not null,slug_fa text not null unique,slug_en text not null unique,is_published boolean not null default false,position integer not null default 0 check(position>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.editorial_entries(id bigint generated always as identity primary key,category_id bigint references public.media_categories(id) on delete set null,kind text not null check(kind in ('news','article','guide')),cover_image_url text,video_url text,cta_url text,is_featured boolean not null default false,is_published boolean not null default false,published_at timestamptz,position integer not null default 0 check(position>=0),created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint editorial_publish_date check(not is_published or published_at is not null));
create table public.editorial_translations(id bigint generated always as identity primary key,entry_id bigint not null references public.editorial_entries(id) on delete cascade,locale text not null check(locale in ('fa','en')),title text not null,slug text not null,excerpt text,body_markdown text not null default '',content_blocks jsonb not null default '[]'::jsonb check(jsonb_typeof(content_blocks)='array'),cta_label text,seo_title text,seo_description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(entry_id,locale),unique(locale,slug));
create index editorial_entries_kind_published_idx on public.editorial_entries(kind,published_at desc) where is_published;
create index editorial_entries_category_idx on public.editorial_entries(category_id,published_at desc);
create index editorial_translations_entry_idx on public.editorial_translations(entry_id);
create trigger media_categories_set_updated_at before update on public.media_categories for each row execute function private.set_updated_at();create trigger editorial_entries_set_updated_at before update on public.editorial_entries for each row execute function private.set_updated_at();create trigger editorial_translations_set_updated_at before update on public.editorial_translations for each row execute function private.set_updated_at();
alter table public.media_categories enable row level security;alter table public.editorial_entries enable row level security;alter table public.editorial_translations enable row level security;
create policy media_categories_public_read on public.media_categories for select to anon,authenticated using(is_published);
create policy editorial_entries_public_read on public.editorial_entries for select to anon,authenticated using(is_published and published_at<=now());
create policy editorial_translations_public_read on public.editorial_translations for select to anon,authenticated using(exists(select 1 from public.editorial_entries e where e.id=entry_id and e.is_published and e.published_at<=now()));
create policy media_categories_staff_manage on public.media_categories for all to authenticated using((select private.has_staff_role(array['manager','admin','seo']))) with check((select private.has_staff_role(array['manager','admin','seo'])));
create policy editorial_entries_staff_manage on public.editorial_entries for all to authenticated using((select private.has_staff_role(array['manager','admin','seo']))) with check((select private.has_staff_role(array['manager','admin','seo'])));
create policy editorial_translations_staff_manage on public.editorial_translations for all to authenticated using((select private.has_staff_role(array['manager','admin','seo']))) with check((select private.has_staff_role(array['manager','admin','seo'])));
grant select on public.media_categories,public.editorial_entries,public.editorial_translations to anon,authenticated;grant insert,update,delete on public.media_categories,public.editorial_entries,public.editorial_translations to authenticated;grant usage,select on all sequences in schema public to authenticated;
